import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 기준으로 생성할 때 생성 일수 = 기본 일수 + 가산 일수(없으면 0)

function isNumeric(v: unknown): boolean {
  if (typeof v === 'number') {
    return Number.isFinite(v);
  }
  if (typeof v === 'string') {
    return /^-?\d+(\.\d+)?$/.test(v.trim());
  }
  return false;
}

function isIntegerValue(v: unknown): boolean {
  return isNumeric(v) && Number.isInteger(Number(v));
}

@Controller('api/v1')
export class FnSfr01902Controller {
  @Post('/annual-leaves')
  @HttpCode(200)
  async createAnnualLeave(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body);
    if (!isIntegerValue(data['employeeId'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '임직원을 선택해 주세요.');
    }
    if (!isIntegerValue(data['leaveYear'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '대상 연도를 숫자로 입력해 주세요.');
    }
    const hasRule = data['leaveGrantRuleId'] !== undefined && data['leaveGrantRuleId'] !== null && data['leaveGrantRuleId'] !== '';
    if (hasRule && !isIntegerValue(data['leaveGrantRuleId'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '연차 생성 기준 형식이 올바르지 않습니다.');
    }
    const hasDays = data['grantedDays'] !== undefined && data['grantedDays'] !== null && data['grantedDays'] !== '';
    if (hasDays && (!isNumeric(data['grantedDays']) || Number(data['grantedDays']) < 0)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '생성 일수는 0 이상의 숫자여야 합니다.');
    }
    const employeeId = String(data['employeeId']);
    const leaveYear = String(data['leaveYear']);
    return transaction(async (db) => {
      const employees = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '임직원을 찾을 수 없습니다.');
      }
      let ruleId: string | null = null;
      let ruleDays: number | null = null;
      if (hasRule) {
        const rules = await db.query(
          `SELECT base_days + COALESCE(additional_days, 0) AS "days"
             FROM leave_grant_rule
            WHERE leave_grant_rule_id = CAST(:ruleId AS bigint)
              AND use_status = '사용'`,
          { ruleId: String(data['leaveGrantRuleId']) },
        );
        if (rules.length === 0) {
          throw new ApiError(422, 'LEAVE_GRANT_RULE_NOT_SET', '연차 생성 기준이 설정되어 있지 않아 생성할 수 없습니다.');
        }
        ruleId = String(data['leaveGrantRuleId']);
        ruleDays = Number(rules[0]['days']);
      }
      let grantedDays: number;
      if (hasDays) {
        grantedDays = Number(data['grantedDays']);
      } else if (ruleDays !== null) {
        grantedDays = ruleDays;
      } else {
        throw new ApiError(422, 'LEAVE_GRANT_RULE_NOT_SET', '연차 생성 기준이 설정되어 있지 않아 생성할 수 없습니다.');
      }
      const existing = await db.query(
        `SELECT annual_leave_id AS "annualLeaveId", confirm_status AS "confirmStatus"
           FROM annual_leave
          WHERE employee_id = CAST(:employeeId AS bigint)
            AND leave_year = CAST(:leaveYear AS integer)
          FOR UPDATE`,
        { employeeId, leaveYear },
      );
      if (existing.length > 0) {
        if (existing[0]['confirmStatus'] === '확정') {
          throw new ApiError(409, 'ANNUAL_LEAVE_ALREADY_CONFIRMED', '이미 확정된 연차입니다. 연차조정 절차를 이용해 주세요.');
        }
        // 가정: 미확정 연차를 다시 생성하면 생성 일수와 기준을 갱신한다
        const updated = await db.query(
          `UPDATE annual_leave
              SET granted_days = CAST(:grantedDays AS numeric),
                  leave_grant_rule_id = CAST(:ruleId AS bigint),
                  updated_at = now()
            WHERE annual_leave_id = CAST(:annualLeaveId AS bigint)
        RETURNING annual_leave_id AS "annualLeaveId", granted_days AS "grantedDays", confirm_status AS "confirmStatus"`,
          { grantedDays, ruleId, annualLeaveId: String(existing[0]['annualLeaveId']) },
        );
        return updated[0];
      }
      const rows = await db.query(
        `INSERT INTO annual_leave
           (employee_id, leave_grant_rule_id, leave_year, granted_days, confirm_status, created_at, updated_at)
         VALUES
           (CAST(:employeeId AS bigint), CAST(:ruleId AS bigint), CAST(:leaveYear AS integer), CAST(:grantedDays AS numeric), '미확정', now(), now())
         RETURNING annual_leave_id AS "annualLeaveId", granted_days AS "grantedDays", confirm_status AS "confirmStatus"`,
        { employeeId, ruleId, leaveYear, grantedDays },
      );
      return rows[0];
    });
  }

  @Post('/annual-leaves/:annualLeaveId/confirm')
  @HttpCode(200)
  async confirmAnnualLeave(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const annualLeaveId = req.params['annualLeaveId'];
    if (!/^\d+$/.test(annualLeaveId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '연차 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT confirm_status AS "confirmStatus"
           FROM annual_leave
          WHERE annual_leave_id = CAST(:annualLeaveId AS bigint)
          FOR UPDATE`,
        { annualLeaveId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ANNUAL_LEAVE_NOT_FOUND', '대상 연차를 찾을 수 없습니다.');
      }
      if (rows[0]['confirmStatus'] !== '미확정') {
        throw new ApiError(409, 'ANNUAL_LEAVE_ALREADY_CONFIRMED', '이미 확정된 연차입니다.');
      }
      // 가정: 확정 일시는 현재 시각
      const updated = await db.query(
        `UPDATE annual_leave
            SET confirm_status = '확정',
                confirmed_at = now(),
                updated_at = now()
          WHERE annual_leave_id = CAST(:annualLeaveId AS bigint)
      RETURNING annual_leave_id AS "annualLeaveId", confirm_status AS "confirmStatus"`,
        { annualLeaveId },
      );
      return updated[0];
    });
  }
}

