import { useState } from 'react';
import {
  call,
  Badge,
  Band,
  DataTable,
  DateInput,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  RefName,
  Tiles,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr01902Page({ role, notify }: PageProps) {
  // 조회 API가 없어 이 화면에서 생성·확정한 결과를 목록으로 보인다
  const [rows, setRows] = useState<Row[]>([]);
  const [creating, setCreating] = useState(false);
  const [target, setTarget] = useState<Row | null>(null);
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [leaveYear, setLeaveYear] = useState<number | string>(new Date().getFullYear());
  const [ruleId, setRuleId] = useState<number | string>('');
  const [grantedDays, setGrantedDays] = useState<number | string>('');

  const unconfirmed = rows.filter((r) => r.confirmStatus === '미확정').length;
  const confirmed = rows.filter((r) => r.confirmStatus === '확정').length;

  function openCreate() {
    setEmployeeId('');
    setRuleId('');
    setGrantedDays('');
    setCreating(true);
  }

  async function submitCreate() {
    if (employeeId === '') {
      throw new Error('임직원을 선택해 주세요.');
    }
    if (leaveYear === '') {
      throw new Error('대상 연도를 입력해 주세요.');
    }
    if (ruleId === '' && grantedDays === '') {
      throw new Error('연차 생성 기준을 선택하거나 생성 일수를 입력해 주세요.');
    }
    const res = await call('POST', '/annual-leaves', role, {
      employeeId,
      leaveYear,
      leaveGrantRuleId: ruleId === '' ? undefined : ruleId,
      grantedDays: grantedDays === '' ? undefined : grantedDays,
    });
    const next: Row = { ...res, employeeId, leaveYear };
    setRows((prev) => [next, ...prev.filter((r) => r.annualLeaveId !== res.annualLeaveId)]);
    setCreating(false);
    notify('연차를 생성했습니다.');
  }

  async function submitConfirm() {
    if (!target) {
      return;
    }
    const res = await call('POST', `/annual-leaves/${target.annualLeaveId}/confirm`, role, {});
    setRows((prev) =>
      prev.map((r) => (r.annualLeaveId === target.annualLeaveId ? { ...r, ...res } : r)),
    );
    setTarget(null);
    notify('연차를 확정했습니다.');
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>생성 건수</h2>
        <Tiles items={[['이번 처리', <Num value={rows.length} />]]} />
      </section>
      <section className="box span-4">
        <h2>확정 대기</h2>
        <Tiles items={[['미확정', <Num value={unconfirmed} />]]} />
      </section>
      <section className="box span-4">
        <h2>확정 완료</h2>
        <Tiles items={[['확정', <Num value={confirmed} />]]} />
      </section>
      <section className="box span-12">
        <h2>연차 생성 결과</h2>
        <Band total={rows.length}>
          <button type="button" onClick={openCreate}>연차 생성</button>
        </Band>
        <DataTable
          rows={rows}
          empty="생성한 연차가 없습니다."
          columns={[
            { key: 'annualLeaveId', label: '연차 ID' },
            {
              key: 'employeeId',
              label: '임직원',
              render: (r) => <RefName table="employee" role={role} value={r.employeeId} />,
            },
            { key: 'leaveYear', label: '대상 연도' },
            { key: 'grantedDays', label: '생성 일수', render: (r) => <Num value={r.grantedDays} /> },
            { key: 'confirmStatus', label: '확정 여부', render: (r) => <Badge value={r.confirmStatus} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                r.confirmStatus === '미확정' ? (
                  <button type="button" onClick={() => setTarget(r)}>확정</button>
                ) : null,
            },
          ]}
        />
      </section>
      {creating && (
        <Drawer title="연차 생성" onClose={() => setCreating(false)}>
          <Form onSubmit={submitCreate} submit="생성">
            <Field label="임직원" required>
              <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
            </Field>
            <Field label="대상 연도" required>
              <NumberInput value={leaveYear} onChange={setLeaveYear} />
            </Field>
            <Field label="연차 생성 기준" hint="기준을 고르면 기본 일수와 가산 일수로 산정합니다.">
              <LookupSelect table="leave_grant_rule" role={role} value={ruleId} onChange={setRuleId} />
            </Field>
            <Field label="생성 일수" hint="미입력 시 기준으로 산정">
              <NumberInput value={grantedDays} onChange={setGrantedDays} />
            </Field>
          </Form>
        </Drawer>
      )}
      {target && (
        <Drawer title="연차 확정" onClose={() => setTarget(null)}>
          <Form
            onSubmit={submitConfirm}
            submit="확정"
            note="확정 후에는 연차조정 절차 없이 수정할 수 없습니다."
          >
            <Field label="임직원">
              <RefName table="employee" role={role} value={target.employeeId} />
            </Field>
            <Field label="생성 일수">
              <Num value={target.grantedDays} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
